/**
 * Proposal PDF Generator
 * Generates a professional proposal document for the insured to review and sign
 */


export interface ProposalData {
  // Quote Information
  quoteNumber: string;
  proposalDate: string;
  desiredCoverageDates?: string;	
  agentName?: string;
  agencyAddress?: string;
  agencyState?: string;
  agencyZip?: string;
  agencyCity?: string;
  classCode?: string;
  // Insured Information
  companyName?: string;
  dba?: string;
  firstName?: string;
  lastName?: string;
  entityType?: string;
  companyFEIN?: string;
  phone?: string;
  email?: string;
  streetAddress?: string;
  city?: string;
  state?: string;
  zipCode?: string;
  grossReceipts?: string;
  
  // Agency Information
  agencyName?: string;
  agencyEmail?: string;
  agencyPhone?: string;
  
  // Carrier Information
  carrierName?: string;
  carrierReference?: string;
  
  // Policy Information
  programName?: string;
  effectiveDate?: string;
  expirationDate?: string;
  occurrenceLimit?: string;
  productsCompletedOpsLimit?: string;
  personalAdvertisingInjuryLimit?: string;
  fireLegalLimit?: string;
  medicalExpenseLimit?: string;
  aggregateLimit?: string;
  deductible?: string;
  selfInsuredRetention?: string;

  
  // Premium Breakdown
  carrierQuoteUSD?: number;
  // No wholesale fee - removed per user request
  premiumTaxPercent?: number;
  premiumTaxAmountUSD?: number;
  policyFeeUSD?: number;
  brokerFeeAmountUSD?: number;
  finalAmountUSD?: number;
  subcontractorCosts?: string;
  
  // Limits
  limits?: {
    generalLiability?: string;
    aggregateLimit?: string;
    fireLegalLimit?: string;
    medicalExpenseLimit?: string;
    deductible?: string;
  };
  
  // Endorsements
  endorsements?: string[];
  
  // Special Notes
  specialNotes?: string;

  // Additional Data
  applicationId?: string | number;
  capitalCoLogoSVG?: string;
  employeePayroll?: string;
  descriptionOfOperations?: string;
}

//svg image 
const capitalLogo = "data:image/png;base64,";
const blueAngelLogo = "data:image/png;base64,";
const sjiLogo = "data:image/png;base64,";


function generateAgencyLogoHTML(logo: string) {
  return `
    <div style="
      position:absolute;
      top:270px;
      left:48%;
      transform:translateX(-50%);
      width:650px;
      height:420px;
      background:white;
      display:flex;
      align-items:center;
      justify-content:center;
      z-index:10;
    ">
      <img src="${logo}" style="width:520px;" />
    </div>
  `;
}
